$issues=@()
foreach($server in $queue.gpu_queues.PSObject.Properties){foreach($task in $server.Value | Where-Object status -in @('"'running','waiting')){"'$registry=Get-Content -LiteralPath ('"'pipeline/experiments/'+"'$task.id+'"'.json') -Raw | ConvertFrom-Json
if("'$registry.id -ne $task.id -or $registry.config -ne $task.config -or $registry.status -ne $task.status -or $registry.server -ne $server.Name){$issues+=$task.id}
if(-not (Test-Path -LiteralPath ('"'Cluster/'+"'$task.config))){$issues+=('"'config:'+ "'$task.id)}
[PSCustomObject]@{ID=$task.id;Status=$task.status;Server=$server.Name;GPU=$registry.gpu;Hold=$task.dispatch_hold}}}
if($issues.Count){throw ($issues -join '"',')}
Import-Csv -LiteralPath pipeline/experiments.csv | Where-Object { "'$_.finished_at -ge '"'2026-09-06' } | ForEach-Object {[PSCustomObject]@{ID="'$_.id;State=$_.state;AnalysisCount=@(Get-ChildItem -LiteralPath pipeline/analyses -Filter ($_.id+'"'_'+"'$_.state+'"'_*.md')).Count}}"

