"C:\\Users\\chuanle song\\AppData\\Local\\Microsoft\\WindowsApps\\pwsh.exe" -Command '$ErrorActionPreference='"'Stop'
"'$memory=Get-Content -LiteralPath pipeline/codex_memory.md
$required=@('"'Goal And Phase','Champion And Baseline','Active Hypotheses','Closed Or Failed Directions','Running And Queue','Open Questions And Risks','Last Tick')
if("'$memory.Count -ge 200){throw '"'Memory too long'}
foreach("'$section in $required){if($memory -notcontains ('"'## '+"'$section)){throw ('"'Missing '+"'$section)}}
$report=Get-Content -LiteralPath pipeline/reports/summary_20260910-002000.md -Raw
foreach($section in @('"'0. Goal Status','1. GPU Overview','2. Running Experiments','3. Queue Status','4. This Tick''s Actions','5. Decisions Made','⚠ Pending User Decisions')){if(-not "'$report.Contains('"'## '+"'$section)){throw ('"'Missing report '+"'$section)}}
$cutoff=(Get-Date).AddHours(-24)
$expired=@(Get-ChildItem -LiteralPath pipeline/reports -Filter '"'summary_*.md' | Where-Object {"'$_.Name -match '"'"'^summary_('"\\d{8}-\\d{6})(?:_manual)?\\.md"'$'"' -and [datetime]::ParseExact("'$Matches[1],'"'yyyyMMdd-HHmmss',[Globalization.CultureInfo]::InvariantCulture) -lt "'$cutoff})
if($expired.Count){throw ('"'Expired summaries remain: '+("'$expired.Name -join '"','))}
"'$questions=@(Get-ChildItem -LiteralPath pipeline/decisions -Filter '"'*_question.md' | Where-Object {"'$_.Name -match '"'"'^('"\\d{8}-\\d{6})_question.md"'$'"' -and [datetime]::ParseExact("'$Matches[1],'"'yyyyMMdd-HHmmss',[Globalization.CultureInfo]::InvariantCulture) -gt "'$cutoff})
if($questions.Count -ne 1){throw '"'Question list changed'}
"'$expected=@{'"'pipeline/goal.json'='4FD79C4649D9B2B43F87D9689A4B17A8DE3B7568BBA6886C7F7075B67B643780';'pipeline/queue.json'='266D2BC44986AA7B95211F8F3F6FBD8FCD45A8629D1ACEE00FD77D49B80B5443';'pipeline/experiments.csv'='23EFA3C43B74CC8C6413E4A7CCE6911360905D6FE8C247B55133D4B6C6C30BAD'}
foreach("'$entry in $expected.GetEnumerator()){if((Get-FileHash -LiteralPath $entry.Key).Hash -ne $entry.Value){throw ('"'State changed '+"'$entry.Key)}}
Write-Output ('"'Memory lines='+"'$memory.Count+'"'; seven sections; report six sections plus questions; expired summaries=0; recent questions=1; state hashes verified')
Test-Path -LiteralPath pipeline/headless/.tick_unhealthy
 git -C Cluster status --short
Get-Date -Format o"

